return HeroFeedbackSurface(
  flashController: heroFlashController,
  onPlayPause: () => player.playPause(),
  onPrevious: () => player.previous(),
  onNext: () => player.next(),
  onSeek: (d) => player.seek(d),
  positionMs: () => player.songInfo?.position ?? 0,
  durationMs: () => player.songInfo?.duration ?? 0,
  showCenterSeekHud: !linuxSeekFeedbackEnabled,
  onSeekFeedbackUpdate:
      linuxSeekFeedbackEnabled
          ? ({
              required target,
              required duration,
              required fraction,
            }) {
              linuxSeeking.value = true;
              linuxSeekTargetMs.value = target.inMilliseconds;
              linuxSeekDurationMs.value = duration.inMilliseconds;
              linuxSeekFraction.value = fraction;
            }
          : null,
  onSeekFeedbackClear: linuxSeekFeedbackEnabled
      ? () {
          linuxSeeking.value = false;
          linuxSeekTargetMs.value = 0;
          linuxSeekDurationMs.value = 0;
          linuxSeekFraction.value = 0.0;
        }
      : null,
  onVerticalDragUpdate: acceptVertical ? onHeroVerticalDrag : null,
  onVerticalDragEnd: acceptVertical ? onHeroVerticalDragEnd : null,
  child: child,
);

